    register: function(email, pw) {

        // Existing registration process.
        this.info("Starting registration process");

        var instance = gs.getProperty('instance_name'),
            username = "onpage";

        // Existing OnPage integration user creation.
        var snPassword = this._createUser();

        // NEW: Stop if integration user setup failed.
        if (!snPassword) {
            this.error("OnPage integration user setup failed.");
            return;
        }

        var snPasswordString = snPassword.toString();

        var rest = new sn_ws.RESTMessageV2(
            "Register with OnPage",
            "Register"
        );

        // Existing request parameters - unchanged.
        rest.setStringParameterNoEscape('URLsub', this.URLsub);
        rest.setStringParameterNoEscape('dispEmail', email);
        rest.setStringParameterNoEscape('dispPass', pw);
        rest.setStringParameterNoEscape('instance', instance);
        rest.setStringParameterNoEscape('username', username);
        rest.setStringParameterNoEscape('password', snPasswordString);

        try {

            // NEW: Identify the asynchronous response in ECC Queue.
            rest.setEccTopic('ONPAGE_REGISTER');

            // CHANGED: Replaced execute() with executeAsync().
            // No waitForResponse(), getBody(), or getStatusCode().
            rest.executeAsync();

            this.info(
                "OnPage registration request queued."
            );

            // CHANGED: Target synchronization now starts
            // after the registration response is processed.

        } catch (ex) {

            this.error(
                "OnPage registration request failed: " +
                (ex.message || String(ex))
            );
        }
    },

    // NEW: Process the registration response received
    // asynchronously through ECC Queue.
    processRegistrationResponse: function(status, body, errorMessage) {

        // Handle unsuccessful registration.
        if (String(status) != '200') {

            this.error(
                "Automatic registration process failed. " +
                "HTTP Status: " + status
            );

            this._handleErrors(
                '',
                status,
                errorMessage || body
            );

            return false;
        }

        try {

            // Existing: Parse registration response.
            var json = JSON.parse(body);

            if (
                !json.credentials ||
                !json.credentials.token ||
                !json.credentials.secretKey
            ) {
                throw new Error(
                    "Registration response does not contain " +
                    "the required credentials."
                );
            }

            var token = json.credentials.token;
            var key = json.credentials.secretKey;

            // CHANGED: Never log authentication credentials.
            this.info(
                "OnPage registration credentials received."
            );

            // Existing subflow: Update token property.
            var tokenInputs = {};

            tokenInputs['system_property'] =
                'x_onpr_onpage.auth.token';

            tokenInputs['new_value'] = token;

            var tokenResult = sn_fd.FlowAPI.getRunner()
                .subflow('x_onpr_onpage.update_system_property')
                .inForeground()
                .withInputs(tokenInputs)
                .run();

            // Existing subflow: Update key property.
            var keyInputs = {};

            keyInputs['system_property'] =
                'x_onpr_onpage.auth.key';

            keyInputs['new_value'] = key;

            var keyResult = sn_fd.FlowAPI.getRunner()
                .subflow('x_onpr_onpage.update_system_property')
                .inForeground()
                .withInputs(keyInputs)
                .run();

            this.info(
                "OnPage credential update subflows completed."
            );

            // CHANGED: Target sync starts after the
            // credential update subflows have executed.
            var syncTargets = new x_onpr_onpage.sync();

            syncTargets.targetSync();

            this.info(
                "OnPage registration response processed. " +
                "Target synchronization initiated."
            );

            return true;

        } catch (ex) {

            // NEW: Do not start target synchronization
            // when response processing throws an error.
            this.error(
                "OnPage registration processing failed: " +
                (ex.message || String(ex))
            );

            return false;
        }
    },

    setupIA: function() {
        var script = (function executeRule(current, previous /*null when async*/ ) {
            var updatedBy = current.getValue('sys_updated_by');
            if (updatedBy == 'onpage') {
                return;
            }
            //check if there is are subscriptions for this table
            var prop = gs.getProperty('x_onpr_onpage.subscription.tables'),
                tables = prop.split(","),
                table = current.getTableName();
            if (tables.indexOf(table) == -1) {
                return;
            }
            var jsonCurrent = new global.JSON().encode(current);
            var jsonPrevious = new global.JSON().encode(previous);
            var gr = new GlideRecordSecure('x_onpr_onpage_event');
            gr.initialize();
            gr.setValue('table', current.getTableName());
            gr.setValue('document_id', current.sys_id);
            gr.setValue('status', 'new');
            gr.setValue('type', 'outbound');
            gr.setValue('current', jsonCurrent);
            gr.setValue('previous', jsonPrevious);
            gr.insert();

        })(current, previous);


        var gr = new GlideRecordSecure('sys_script');
        gr.initialize();
        gr.setValue('collection', "incident_alert");
        gr.setValue('name', "Generate OnPage events from IA Updates");
        gr.setValue('action_insert', 'true');
        gr.setValue('action_update', 'true');
        gr.setValue('advanced', 'true');
        gr.setValue('script', script);
        gr.insert();
    },
    _createUser: function() {
        this.info("Create User function starting");

        //check for existing account
        var sys_id;
        var gr = new GlideRecordSecure('sys_user');
        gr.addQuery('user_name', "onpage");
        gr.query();
        if (gr.next()) {
            //if exists, update password
            this.info("OnPage user already exists.");
            sys_id = gr.getUniqueValue();
            gr.user_password.setDisplayValue(sys_id);
            gr.update();
        } else {
            //doesn't exist, create user
            this.info("OnPage user does not exist. Creating.");
            gr.initialize();
            gr.setValue('user_name', "onpage");
            gr.setValue('first_name', "OnPage");
            gr.setValue('last_name', "Integration");
            gr.setValue('web_service_access_only', true);
            gr.insert();
            sys_id = gr.getUniqueValue();
            gr.user_password.setDisplayValue(sys_id);
            gr.update();
        }
        //check for user roles
        this.info("Checking for user roles.");
        var role = new GlideRecordSecure('sys_user_role');
        if (role.get("name", "x_onpr_onpage.integration_user")) {
            var roleGR = new GlideRecordSecure('sys_user_has_role');
            roleGR.addQuery('user', sys_id);
            roleGR.addQuery('role', role.getUniqueValue());
            roleGR.query();
            if (roleGR.next()) {
                //if existing, do nothing
                this.info("OnPage user has roles. No changes to make.");
            } else {
                //not existing, create record
                this.info("OnPage user does not have roles. Adding role.");
                var grantRole = new GlideRecordSecure('sys_user_has_role');
                grantRole.initialize();
                grantRole.setValue('user', sys_id);
                grantRole.setValue('role', role.getUniqueValue());
                grantRole.insert();
            }
            this.info("create user sys id:" + sys_id);
            return sys_id;
        }
    },
    _handleErrors: function(request, status, body) {
        var handle = new x_onpr_onpage.handleErrors();
        handle.rest(request, status, body);
    },
    type: 'setup'
};
